//! 🧪️ Two actual native Window partitions share one complete visibility epoch and exact source closure.
use super::*;
use crate::original_genesis_tests::{Owner,State,Mutation};
use crate::semantic_preview::tests::{turn,grant,wide,typed_close};
use semio_framework_job::{OriginalJobFixtureCaller,OriginalJobDecodeOwner,OperationId,Generation};
use semio_framework_value::retained_clone::original_slot::RetainedOriginalSlot;
fn caller()->OriginalJobFixtureCaller{OriginalJobFixtureCaller::admit(OperationId(8901),Generation(8),RetainedCloneGrant{maximum_items:1<<28,maximum_copy_bytes:1<<30,maximum_capacity_bytes:1<<28,maximum_release_bytes:1<<28,maximum_depth:4096},semio_framework_job::default_now_us,u64::MAX,1<<29)}
fn visible(registry:&WindowConfigOwnerRegistry,windows:&[&str;2])->[f64;2]{windows.map(|window|registry.borrow_preview(Owner::WINDOW_KIND_ID,window).unwrap().get::<Owner>().unwrap().zoom)}
fn denied(d:RetirementDemand,mut run:impl FnMut(RetainedCloneGrant)) {let exact=grant(d);for axis in 0..5{let mut g=exact;match axis{0=>g.maximum_items=0,1 if d.copy_bytes>0=>g.maximum_copy_bytes-=1,2 if d.capacity_bytes>0=>g.maximum_capacity_bytes-=1,3 if d.release_bytes>0=>g.maximum_release_bytes-=1,4 if d.depth>0=>g.maximum_depth-=1,_=>continue}run(g)}}
fn leaf(registry:&mut WindowConfigOwnerRegistry,epoch:u64,window:&str,value:f64,caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner){
 let mut slot=RetainedOriginalSlot::new(WindowConfigMutation::of::<Owner>(window,Mutation::Zoom{zoom:value}));let key=slot.key();let pointer=slot.get().mutation.as_any().downcast_ref::<Mutation>().unwrap()as*const Mutation;let factory:Arc<dyn store::ArtifactOwnedValueRetirementFactory<WindowConfigMutation>>=Arc::new(semio_framework_value::factory::OwnedValueRetirementFactory::<WindowConfigMutation>::default());
 while slot.borrow(key).is_err(){let d=slot.demands(key).unwrap();turn(caller,decoder,grant(d),|cx|{cx.consume_retained(slot.advance_read(key,&factory,grant(d))?.progress())?;cx.consume_fuel(1);Ok(())});}
 let d=semio_framework_value::RetainedOwnedProjection::<WindowConfigMutation>::constructor_demand();let mut input=turn(caller,decoder,grant(d),|cx|{let(input,p)=slot.retain_read(key,grant(d))?;cx.consume_retained(p)?;cx.consume_fuel(1);Ok(input)});
 for index in 0..64{if registry.preview_input_held(Owner::WINDOW_KIND_ID,window,epoch){break}let d=registry.preview_input_demands(Owner::WINDOW_KIND_ID,window,epoch,4096).unwrap();turn(caller,decoder,grant(d),|cx|{paid(cx,d,|g|Ok(registry.preview_input(&input,epoch,g)?.unwrap_or_default()))?;Ok(())});assert!(index<63,"original epoch leaf admission stalled");}
 while !input.terminal_is_empty(){let d=input.close_demand(4096).unwrap();turn(caller,decoder,grant(d),|cx|{semio_framework_job::close_original_retained_step(cx,d,|g|input.close_step(g))?;Ok(())});}
 for index in 0..65536{if registry.preview_leaf_ready(Owner::WINDOW_KIND_ID,window,epoch){break}let d=registry.preview_leaf_demands(Owner::WINDOW_KIND_ID,window,epoch,4096).unwrap();denied(d,|g|turn(caller,decoder,g,|cx|{receive(cx,d,|native,g|registry.preview_leaf_step(Owner::WINDOW_KIND_ID,window,epoch,4096,g,native).map(|(_,p)|RetainedCloneStep::Progress(p)))?;Ok(())}));turn(caller,decoder,grant(d),|cx|receive(cx,d,|native,g|registry.preview_leaf_step(Owner::WINDOW_KIND_ID,window,epoch,4096,g,native).map(|(_,p)|RetainedCloneStep::Progress(p))));assert!(index<65535,"original epoch semantic leaf stalled");}
 assert_eq!(slot.get().mutation.as_any().downcast_ref::<Mutation>().unwrap()as*const Mutation,pointer);typed_close(slot,caller,decoder);typed_close(semio_framework_value::FactoryAuthority::new(factory),caller,decoder);
}
#[test]
fn original_window_epoch_publishes_complete_pair_and_cancels_private_pair(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let windows=[law["windows"][0].as_str().unwrap(),law["windows"][1].as_str().unwrap()];let mut caller=caller();let mut decoder=OriginalJobDecodeOwner::empty();let mut registry=WindowConfigOwnerRegistry::new(protocol::ActorId("epoch-actor".into()));registry.register::<Owner>().unwrap();
 for window in windows{for index in 0..262144{if turn(&mut caller,&mut decoder,crate::original_genesis_tests::grant(),|cx|registry.owners.get_mut(Owner::WINDOW_KIND_ID).unwrap().ensure_partition(window,cx)){break}assert!(index<262143,"original epoch partition birth stalled");}}
 let mut expected=[1.25,1.25];assert_eq!(visible(&registry,&windows),expected);
 for case in law["epochs"].as_array().unwrap(){let mut epoch=None;let d=OriginalWindowPreviewEpoch::admission_demands();denied(d,|g|{assert!(!turn(&mut caller,&mut decoder,g,|cx|OriginalWindowPreviewEpoch::admit(&mut registry,4096,cx,&mut epoch)));assert!(registry.preview_active_epoch.is_none())});turn(&mut caller,&mut decoder,grant(d),|cx|OriginalWindowPreviewEpoch::admit(&mut registry,4096,cx,&mut epoch));let epoch=epoch.as_mut().unwrap();
  if let Some(values)=case["values"].as_array(){for(index,window)in windows.iter().enumerate(){leaf(&mut registry,epoch.epoch(),window,values[index].as_f64().unwrap(),&mut caller,&mut decoder);assert_eq!(visible(&registry,&windows),expected)}}
  for index in 0..65536{if epoch.ready(){break}let d=epoch.demands(&registry).unwrap();denied(d,|g|{assert!(!turn(&mut caller,&mut decoder,g,|cx|epoch.advance(&mut registry,cx)));assert_eq!(caller.receipt(),Default::default());assert_eq!(visible(&registry,&windows),expected)});turn(&mut caller,&mut decoder,grant(d),|cx|epoch.advance(&mut registry,cx));assert_eq!(visible(&registry,&windows),expected);assert!(index<65535,"original epoch candidate preparation stalled");}
  if case["publish"].as_bool().unwrap(){let d=epoch.publication_demands();denied(d,|g|{turn(&mut caller,&mut decoder,g,|cx|{epoch.validate_context(&registry,cx)?;receive(cx,d,|native,g|Ok(RetainedCloneStep::Progress(epoch.publish_granted(&mut registry,g,native)?.unwrap_or_default())))?;Ok(())});assert_eq!(visible(&registry,&windows),expected)});turn(&mut caller,&mut decoder,grant(d),|cx|{epoch.validate_context(&registry,cx)?;receive(cx,d,|native,g|Ok(RetainedCloneStep::Progress(epoch.publish_granted(&mut registry,g,native)?.unwrap_or_default())))?;Ok(())});expected=case["visible"].as_array().unwrap().iter().map(|v|v.as_f64().unwrap()).collect::<Vec<_>>().try_into().unwrap();}
  if case["cancelCaller"].as_bool()==Some(true){assert!(std::future::Future::poll(std::pin::pin!(caller.cancel().cancel()).as_mut(),&mut std::task::Context::from_waker(std::task::Waker::noop())).is_ready())}
  for index in 0..65536{if epoch.terminal_is_empty(){break}let d=epoch.close_demands(&registry).unwrap();denied(d,|g|{assert!(!turn(&mut caller,&mut decoder,g,|cx|epoch.close_step(&mut registry,cx)));assert_eq!(caller.receipt(),Default::default());assert_eq!(visible(&registry,&windows),expected)});turn(&mut caller,&mut decoder,grant(d),|cx|epoch.close_step(&mut registry,cx));assert_eq!(visible(&registry,&windows),expected);assert!(index<65535,"original epoch cleanup stalled at owner {} partition {} demand {d:?}",epoch.owner,epoch.partition);}
  assert_eq!(visible(&registry,&windows),expected);assert!(registry.preview_active_epoch.is_none());
 }
 for index in 0..1048576{if registry.terminal_is_empty(){break}let d=registry.retirement_demands(4096).unwrap();turn(&mut caller,&mut decoder,RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth.max(1)},|cx|cx.with_original_retirement(|cx|registry.close_step_context(cx.retained_grant(),cx).map(|_|()).map_err(Into::into)));assert!(index<1048575,"original epoch registry closure stalled");}
 while !decoder.terminal_is_empty(){let d=decoder.retirement_demands(4096).unwrap();caller.turn(grant(d),|cx|cx.with_original_retirement(|cx|{semio_framework_job::close_original_retained_step(cx,d,|g|decoder.close_step(g))?;Ok(())})).unwrap();}caller.retire(wide());
}
